/**
 * The decorative SVGs, inlined so a body can take a design-system colour,
 * with a convex hull for each so collisions follow the ink, not the box.
 *
 * Both the registry (`assets.generated.ts`) and the hulls (`hulls.json`) are
 * generated by `npm run decor:hulls` from packages/design-stage/assets. To
 * replace or add an SVG, drop the file in and rerun; a stale hull fails the
 * decor test suite with that command's name.
 *
 * The export bakes a fill and a rotation into each path; the fill is
 * replaced with `currentColor`, the rotation is kept (it is part of the
 * look) and the seeded rotation is applied on top. Never redraw these
 * (design system: "Iconography").
 */

import hulls from '@questiongame/design-stage/assets/hulls.json'
import { RAW_ASSETS, type DecorAssetId } from './assets.generated'

export type { DecorAssetId }

export interface DecorAsset {
  readonly id: DecorAssetId
  /** Natural size from the viewBox — the assets are cut at 1920-canvas scale. */
  readonly width: number
  readonly height: number
  /** Markup with fills replaced by `currentColor` and no fixed size. */
  readonly markup: string
  /** Convex hull in viewBox units, counter-clockwise. */
  readonly hull: readonly (readonly [number, number])[]
  /** FNV-1a of the SVG the hull was computed from (see seed.ts hashString). */
  readonly hullHash: string
}

interface HullEntry {
  readonly file: string
  readonly width: number
  readonly height: number
  readonly hull: readonly (readonly [number, number])[]
  readonly hash: string
}

const HULLS = hulls as unknown as Record<string, HullEntry>

function parse(id: DecorAssetId, raw: string): DecorAsset {
  const vb = /viewBox="([-\d.]+) ([-\d.]+) ([-\d.]+) ([-\d.]+)"/.exec(raw)
  const width = vb ? Number(vb[3]) : 0
  const height = vb ? Number(vb[4]) : 0
  const markup = raw
    .replace(
      /<svg([^>]*)>/,
      (_m, attrs: string) =>
        `<svg${attrs.replace(/\s(width|height)="[^"]*"/g, '')} width="100%" height="100%" preserveAspectRatio="xMidYMid meet">`,
    )
    .replace(/fill="(?!none")[^"]*"/g, 'fill="currentColor"')
    .replace(/stroke="(?!none")[^"]*"/g, 'stroke="currentColor"')
  const h = HULLS[id]
  // A missing hull falls back to the box; the staleness test reports it.
  const hull: readonly (readonly [number, number])[] = h?.hull ?? [
    [0, 0],
    [width, 0],
    [width, height],
    [0, height],
  ]
  return { id, width, height, markup, hull, hullHash: h?.hash ?? '' }
}

const ASSETS = Object.fromEntries(
  (Object.keys(RAW_ASSETS) as DecorAssetId[]).map((id) => [id, parse(id, RAW_ASSETS[id])]),
) as Record<DecorAssetId, DecorAsset>

export function decorAsset(id: string): DecorAsset {
  const a = ASSETS[id as DecorAssetId]
  if (!a) throw new Error(`unknown decor asset "${id}" — is the SVG in packages/design-stage/assets and was \`npm run decor:hulls\` run?`)
  return a
}

export const DECOR_ASSET_IDS = Object.keys(ASSETS) as DecorAssetId[]

/** The raw markup, for the staleness test. */
export function rawAsset(id: DecorAssetId): string {
  return RAW_ASSETS[id]
}
